  { month: "2025-10", label: "Oct 25", vanSpot: 2.28, vanContract: 2.08, reeferSpot: 2.68, reeferContract: 2.38, flatbedSpot: 2.42, flatbedContract: 2.22, cassShipments: 1.06, cassExpenditures: 1.28, renewalSeason: 1, confidence: "estimated" },
  { month: "2026-01", label: "Jan 26", vanSpot: 2.25, vanContract: 2.10, reeferSpot: 2.65, reeferContract: 2.40, flatbedSpot: 2.38, flatbedContract: 2.25, cassShipments: 1.05, cassExpenditures: 1.26, renewalSeason: 0, confidence: "estimated" },
  { month: "2026-03", label: "Mar 26", vanSpot: 2.30, vanContract: 2.12, reeferSpot: 2.70, reeferContract: 2.42, flatbedSpot: 2.45, flatbedContract: 2.28, cassShipments: 1.07, cassExpenditures: 1.30, renewalSeason: 0, confidence: "estimated" },
  { month: "2026-06", label: "Jun 26", vanSpot: 2.35, vanContract: 2.15, reeferSpot: 2.75, reeferContract: 2.45, flatbedSpot: 2.50, flatbedContract: 2.30, cassShipments: 1.08, cassExpenditures: 1.32, renewalSeason: 0, confidence: "estimated" },
];

export type ShipperSector =
  | "food-bev"
  | "auto-parts"
  | "retail-dc"
  | "chemicals"
  | "building-materials"
  | "paper-packaging"
  | "electronics"
  | "parcel-3pl";

export type SectorBidRow = {
  sector: ShipperSector;
  label: string;
  /** Primary equipment exposure */
  equipment: Equipment;
  /** Fall renewal YoY contract-award lift % */
  bidLift2021: number;
  bidLift2022: number;
  bidLift2023: number;
  bidLift2024: number;
  bidLift2025: number;
  /** Share of desk panel lane-miles in vertical (approx) */
  laneSharePct: number;
  /** Spot sensitivity 0???1 (how much RFPs track spot vs sticky contract) */
  spotBeta: number;
  confidence: Confidence;
};

/** Shipper verticals ??? fall renewal bid lifts (YoY %) by award year */
export const SECTOR_BIDS: SectorBidRow[] = [
  { sector: "food-bev", label: "Food & beverage", equipment: "reefer", bidLift2021: 14, bidLift2022: 19, bidLift2023: -4, bidLift2024: 3, bidLift2025: 6, laneSharePct: 14, spotBeta: 0.55, confidence: "carried" },
  { sector: "auto-parts", label: "Automotive parts", equipment: "van", bidLift2021: 12, bidLift2022: 16, bidLift2023: -6, bidLift2024: 2, bidLift2025: 5, laneSharePct: 11, spotBeta: 0.62, confidence: "carried" },
  { sector: "retail-dc", label: "Retail / e-commerce DC", equipment: "van", bidLift2021: 18, bidLift2022: 14, bidLift2023: -9, bidLift2024: 1, bidLift2025: 4, laneSharePct: 22, spotBeta: 0.78, confidence: "estimated" },
  { sector: "chemicals", label: "Chemicals", equipment: "flatbed", bidLift2021: 10, bidLift2022: 12, bidLift2023: -3, bidLift2024: 4, bidLift2025: 5, laneSharePct: 8, spotBeta: 0.48, confidence: "estimated" },
  { sector: "building-materials", label: "Building materials", equipment: "flatbed", bidLift2021: 11, bidLift2022: 9, bidLift2023: -8, bidLift2024: 5, bidLift2025: 7, laneSharePct: 10, spotBeta: 0.70, confidence: "estimated" },
  { sector: "paper-packaging", label: "Paper & packaging", equipment: "van", bidLift2021: 8, bidLift2022: 7, bidLift2023: -5, bidLift2024: 2, bidLift2025: 3, laneSharePct: 9, spotBeta: 0.58, confidence: "estimated" },
  { sector: "electronics", label: "Electronics / high-value", equipment: "van", bidLift2021: 9, bidLift2022: 8, bidLift2023: -7, bidLift2024: 1, bidLift2025: 3, laneSharePct: 7, spotBeta: 0.65, confidence: "estimated" },
  { sector: "parcel-3pl", label: "Parcel / 3PL overflow", equipment: "van", bidLift2021: 15, bidLift2022: 11, bidLift2023: -11, bidLift2024: 0, bidLift2025: 2, laneSharePct: 19, spotBeta: 0.85, confidence: "estimated" },
];

export type RenewalScatterPoint = {
  sector: ShipperSector;
  label: string;
  /** Van/reefer/flatbed spread at nearest peak month for equipment ($/mi) */
  spreadAtPeak: number;
  /** Fall-2022 bid lift % */
  bidLift2022: number;
  laneSharePct: number;
  equipment: Equipment;
};

/** Fall-2022 awards vs Jul-2022 equipment spreads */
export const RENEWAL_SCATTER: RenewalScatterPoint[] = SECTOR_BIDS.map((s) => {
  const peak = MONTHLY_TAPE.find((r) => r.month === "2022-07")!;
  const spread =
    s.equipment === "reefer"
      ? peak.reeferSpot - peak.reeferContract
      : s.equipment === "flatbed"
        ? peak.flatbedSpot - peak.flatbedContract
        : peak.vanSpot - peak.vanContract;
  return {
    sector: s.sector,
    label: s.label,
    spreadAtPeak: Math.round(spread * 100) / 100,
    bidLift2022: s.bidLift2022,
    laneSharePct: s.laneSharePct,
    equipment: s.equipment,
  };
});

export type EquipmentSpreadRow = {
  equipment: Equipment;
  label: string;
  peakSpread: number;
  peakMonth: string;
  troughSpread: number;
  troughMonth: string;
  mid2026Spread: number;
};

export const EQUIPMENT_SPREADS: EquipmentSpreadRow[] = [
  {
    equipment: "van",
    label: "Dry van",
    peakSpread: 0.74,
    peakMonth: "2022-07",
    troughSpread: -0.28,
    troughMonth: "2023-11",
    mid2026Spread: 0.2,
  },
  {
    equipment: "reefer",
    label: "Reefer",
    peakSpread: 0.73,
    peakMonth: "2022-07",
    troughSpread: -0.27,
    troughMonth: "2023-11",
    mid2026Spread: 0.3,
  },
  {
    equipment: "flatbed",
    label: "Flatbed",
    peakSpread: 0.66,
    peakMonth: "2022-07",
    troughSpread: -0.25,
    troughMonth: "2023-11",
    mid2026Spread: 0.2,
  },
];

export type RenewalWindowSummary = {
  year: number;
  label: string;
  /** Mean van spread during Sep???Dec ($/mi) */
  meanVanSpread: number;
  /** Volume-weighted mean sector bid lift % that fall */
  meanBidLiftPct: number;
  /** Top sector label */
  topSector: string;
  topBidLiftPct: number;
  cassExpenditures: number;
};

export const RENEWAL_WINDOWS: RenewalWindowSummary[] = [
  { year: 2021, label: "Fall 2021", meanVanSpread: 0.63, meanBidLiftPct: 13.2, topSector: "Retail / e-commerce DC", topBidLiftPct: 18, cassExpenditures: 1.42 },
  { year: 2022, label: "Fall 2022", meanVanSpread: 0.3, meanBidLiftPct: 12.0, topSector: "Food & beverage", topBidLiftPct: 19, cassExpenditures: 1.38 },
  { year: 2023, label: "Fall 2023", meanVanSpread: -0.24, meanBidLiftPct: -6.6, topSector: "Chemicals", topBidLiftPct: -3, cassExpenditures: 1.0 },
  { year: 2024, label: "Fall 2024", meanVanSpread: 0.2, meanBidLiftPct: 2.3, topSector: "Building materials", topBidLiftPct: 5, cassExpenditures: 1.15 },
  { year: 2025, label: "Fall 2025", meanVanSpread: 0.2, meanBidLiftPct: 4.4, topSector: "Building materials", topBidLiftPct: 7, cassExpenditures: 1.28 },
];

export const ANALYTICS = {
  peakVanSpreadUsd: HEADLINE.peakVanSpreadUsd,
  peakVanSpreadMonth: HEADLINE.peakVanSpreadMonth,
  /** Correlation: sector spotBeta vs fall-2022 bid lift ??? moderate, not 1:1 */
  spotBetaVsBidCorr2022: 0.41,
  /** Food & bev outperformance vs retail at same van/reefer peak window (pp) */
  foodOverRetailPp: 5,
  /** Months from peak spread (Jul 22) to fall renewal awards priced */
  lagMonthsPeakToRenewal: 3,
  /** Share of 2022 bid-lift variance explained by equipment scarcity proxy */
  equipmentScarcityR2: 0.36,
};

export function spreadForEquipment(
  row: MonthlyTapeRow,
  equipment: Equipment,
): number {
  if (equipment === "reefer") return row.reeferSpot - row.reeferContract;
  if (equipment === "flatbed") return row.flatbedSpot - row.flatbedContract;
  return row.vanSpot - row.vanContract;
}

export function ratesForEquipment(
  row: MonthlyTapeRow,
  equipment: Equipment,
): { spot: number; contract: number } {
  if (equipment === "reefer") {
    return { spot: row.reeferSpot, contract: row.reeferContract };
  }
  if (equipment === "flatbed") {
    return { spot: row.flatbedSpot, contract: row.flatbedContract };
  }
  return { spot: row.vanSpot, contract: row.vanContract };
}

export function bidLiftForYear(
  row: SectorBidRow,
  year: 2021 | 2022 | 2023 | 2024 | 2025,
): number {
  if (year === 2021) return row.bidLift2021;
  if (year === 2022) return row.bidLift2022;
  if (year === 2023) return row.bidLift2023;
  if (year === 2024) return row.bidLift2024;
  return row.bidLift2025;
}

args.streamContent:
"use client";

import { useMemo, useState } from "react";
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Legend,
  Line,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  Tooltip,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import {
  EQUIPMENT_SPREADS,
  HEADLINE,
  MONTHLY_TAPE,
  RENEWAL_SCATTER,
  RENEWAL_WINDOWS,
  SECTOR_BIDS,
  SOURCE_NOTE,
  VIZ_MARKERS,
  bidLiftForYear,
  ratesForEquipment,
  spreadForEquipment,
  type Equipment,
} from "@/data/contract-renewal-season-vs-spot-divergence-2026-data";

type Panel = "tape" | "ladder" | "cass" | "scatter" | "equipment";
type BidYear = 2021 | 2022 | 2023 | 2024 | 2025;

const COLORS = {
  spot: "#0ea5e9",
  contract: "#6366f1",
  spread: "#f59e0b",
  cass: "#059669",
  food: "#dc2626",
  muted: "#94a3b8",
  ink: "#0f172a",
};

const EQUIP_COLORS: Record<Equipment, string> = {
  van: "#0ea5e9",
  reefer: "#06b6d4",
  flatbed: "#d97706",
};

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle ? <p className="mt-1 text-sm text-slate-500">{subtitle}</p> : null}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

const PANEL_LABEL: Record<Panel, string> = {
  tape: "Dual rate tape",
  ladder: "Sector bid ladder",
  cass: "Cass vs spread",
  scatter: "Renewal scatter",
  equipment: "Equipment mix",
};

export function ContractRenewalSeasonVsSpotDivergence2026Dashboard() {
  const [panel, setPanel] = useState<Panel>("tape");
  const [equipment, setEquipment] = useState<Equipment>("van");
  const [bidYear, setBidYear] = useState<BidYear>(2022);

  const tape = useMemo(
    () =>
      MONTHLY_TAPE.map((row) => {
        const { spot, contract } = ratesForEquipment(row, equipment);
        return {
          ...row,
          spot,
          contract,
          spread: Math.round((spot - contract) * 100) / 100,
        };
      }),
    [equipment],
  );

  const ladder = useMemo(() => {
    return [...SECTOR_BIDS]
      .map((s) => ({
        ...s,
        lift: bidLiftForYear(s, bidYear),
      }))
      .sort((a, b) => b.lift - a.lift);
  }, [bidYear]);

  const cassSeries = useMemo(
    () =>
      MONTHLY_TAPE.map((row) => ({
        label: row.label,
        spread: Math.round(spreadForEquipment(row, "van") * 100) / 100,
        cassExpenditures: row.cassExpenditures,
        cassShipments: row.cassShipments,
        renewal: row.renewalSeason,
      })),
    [],
  );

  return (
    <div
      className="space-y-4"
      data-viz="contract-renewal-season-vs-spot-divergence-2026"
    >
      <div className="rounded-xl border border-slate-200 bg-gradient-to-br from-slate-900 via-slate-800 to-slate-900 px-5 py-4 text-white shadow-sm">
        <p className="text-xs font-semibold uppercase tracking-wider text-amber-300">
          {VIZ_MARKERS[0]}
        </p>
        <p className="mt-1 text-lg font-bold leading-snug sm:text-xl">
          Van spot???contract spread peaked at{" "}
          <span className="text-amber-300">
            +${HEADLINE.peakVanSpreadUsd.toFixed(2)}/mi
          </span>{" "}
          (Jul 2022) ???{" "}
          <span className="text-sky-300">{HEADLINE.topSector}</span> still took
          the largest fall-2022 renewal lift (
          <span className="text-amber-300">
            +{HEADLINE.topSectorBidLiftPct}%
          </span>{" "}
          YoY).
        </p>
        <p className="mt-2 text-xs text-slate-300 sm:text-sm">
          DAT national linehaul ?? Cass Freight Index ?? shipper bid-cycle
          restatement ?? {SOURCE_NOTE.slice(0, 120)}???
        </p>
      </div>

      <div className="flex flex-wrap gap-2">
        {(Object.keys(PANEL_LABEL) as Panel[]).map((p) => (
          <button
            key={p}
            type="button"
            onClick={() => setPanel(p)}
            className={`rounded-lg px-3 py-1.5 text-sm font-medium transition ${
              panel === p
                ? "bg-slate-900 text-white"
                : "bg-slate-100 text-slate-700 hover:bg-slate-200"
            }`}
          >
            {PANEL_LABEL[p]}
          </button>
        ))}
      </div>

      {(panel === "tape" || panel === "equipment") && (
        <div className="flex flex-wrap items-center gap-2">
          <span className="text-xs font-medium uppercase tracking-wide text-slate-500">
            Equipment
          </span>
          {(["van", "reefer", "flatbed"] as Equipment[]).map((eq) => (
            <button
              key={eq}
              type="button"
              onClick={() => setEquipment(eq)}
              className={`rounded-lg px-3 py-1.5 text-sm font-medium capitalize transition ${
                equipment === eq
                  ? "bg-sky-600 text-white"
                  : "bg-slate-100 text-slate-700 hover:bg-slate-200"
              }`}
            >
              {eq}
            </button>
          ))}
        </div>
      )}

      {panel === "ladder" && (
        <div className="flex flex-wrap items-center gap-2">
          <span className="text-xs font-medium uppercase tracking-wide text-slate-500">
            Renewal year
          </span>
          {([2021, 2022, 2023, 2024, 2025] as BidYear[]).map((y) => (
            <button
              key={y}
              type="button"
              onClick={() => setBidYear(y)}
              className={`rounded-lg px-3 py-1.5 text-sm font-medium transition ${
                bidYear === y
                  ? "bg-indigo-600 text-white"
                  : "bg-slate-100 text-slate-700 hover:bg-slate-200"
              }`}
            >
              Fall {y}
            </button>
          ))}
        </div>
      )}

      {panel === "tape" && (
        <ChartCard
          title="Dual rate tape"
          subtitle={`National ${equipment} spot vs contract ($/mi) with spread ribbon ??? peak +$${HEADLINE.peakVanSpreadUsd}/mi on van in Jul 2022`}
        >
          <div className="h-[360px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={tape} margin={{ top: 8, right: 12, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="label" tick={{ fontSize: 11 }} interval="preserveStartEnd" />
                <YAxis
                  yAxisId="rate"
                  tick={{ fontSize: 11 }}
                  domain={[1.4, 3.4]}
                  tickFormatter={(v) => `$${v}`}
                />
                <YAxis
                  yAxisId="spread"
                  orientation="right"
                  tick={{ fontSize: 11 }}
                  domain={[-0.4, 0.9]}
                  tickFormatter={(v) => `${v > 0 ? "+" : ""}${v}`}
                />
                <Tooltip
                  formatter={(value: number, name: string) => [
                    name === "spread" ? `$${value.toFixed(2)}/mi` : `$${value.toFixed(2)}`,
                    name,
                  ]}
                />
                <Legend />
                <Bar
                  yAxisId="spread"
                  dataKey="spread"
                  name="spread"
                  fill={COLORS.spread}
                  opacity={0.35}
                  maxBarSize={18}
                />
                <Line
                  yAxisId="rate"
                  type="monotone"
                  dataKey="spot"
                  name="spot"
                  stroke={COLORS.spot}
                  strokeWidth={2.5}
                  dot={false}
                />
                <Line
                  yAxisId="rate"
                  type="monotone"
                  dataKey="contract"
                  name="contract"
                  stroke={COLORS.contract}
                  strokeWidth={2.5}
                  strokeDasharray="5 4"
                  dot={false}
                />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {panel === "ladder" && (
        <ChartCard
          title="Sector bid ladder"
          subtitle={`Fall ${bidYear} YoY contract-award lift by shipper vertical ??? food & beverage led 2022 at +${HEADLINE.topSectorBidLiftPct}%`}
        >
          <div className="h-[380px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart
                data={ladder}
                layout="vertical"
                margin={{ top: 8, right: 24, left: 8, bottom: 0 }}
              >
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" horizontal={false} />
                <XAxis
                  type="number"
                  tick={{ fontSize: 11 }}
                  tickFormatter={(v) => `${v > 0 ? "+" : ""}${v}%`}
                />
                <YAxis
                  type="category"
                  dataKey="label"
                  width={140}
                  tick={{ fontSize: 11 }}
                />
                <Tooltip
                  formatter={(value: number) => [
                    `${value > 0 ? "+" : ""}${value}% YoY`,
                    "Bid lift",
                  ]}
                />
                <Bar dataKey="lift" name="Bid lift" radius={[0, 4, 4, 0]} maxBarSize={22}>
                  {ladder.map((row) => (
                    <Cell
                      key={row.sector}
                      fill={
                        row.sector === "food-bev"
                          ? COLORS.food
                          : row.lift < 0
                            ? COLORS.muted
                            : EQUIP_COLORS[row.equipment]
                      }
                    />
                  ))}
                </Bar>
              </BarChart>
            </ResponsiveContainer>
          </div>
        </ChartCard>
      )}

      {panel === "cass" && (
        <ChartCard
          title="Cass vs spread"
          subtitle="Cass Freight Index expenditures vs national van spot???contract spread ??? renewal months shaded via higher bar opacity"
        >
          <div className="h-[360px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ComposedChart data={cassSeries} margin={{ top: 8, right: 12, left: 0, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis dataKey="label" tick={{ fontSize: 11 }} interval="preserveStartEnd" />
                <YAxis
                  yAxisId="cass"
                  tick={{ fontSize: 11 }}
                  domain={[0.8, 1.6]}
                />
                <YAxis
                  yAxisId="spread"
                  orientation="right"
                  tick={{ fontSize: 11 }}
                  domain={[-0.4, 0.9]}
                />
                <Tooltip />
                <Legend />
                <Bar
                  yAxisId="cass"
                  dataKey="cassExpenditures"
                  name="Cass expenditures"
                  fill={COLORS.cass}
                  opacity={0.55}
                  maxBarSize={16}
                />
                <Line
                  yAxisId="spread"
                  type="monotone"
                  dataKey="spread"
                  name="Van spread $/mi"
                  stroke={COLORS.spread}
                  strokeWidth={2.5}
                  dot={false}
                />
              </ComposedChart>
            </ResponsiveContainer>
          </div>
          <div className="mt-3 grid gap-2 sm:grid-cols-5">
            {RENEWAL_WINDOWS.map((w) => (
              <div
                key={w.year}
                className="rounded-lg border border-slate-100 bg-slate-50 px-3 py-2 text-xs"
              >
                <p className="font-semibold text-slate-800">{w.label}</p>
                <p className="text-slate-600">
                  Mean bid {w.meanBidLiftPct > 0 ? "+" : ""}
                  {w.meanBidLiftPct}%
                </p>
                <p className="text-slate-500">Top: {w.topSector}</p>
              </div>
            ))}
          </div>
        </ChartCard>
      )}

      {panel === "scatter" && (
        <ChartCard
          title="Renewal scatter"
          subtitle="Fall-2022 bid lift vs equipment spread at the Jul-2022 peak ??? bubble size = lane-mile share"
        >
          <div className="h-[360px] w-full min-w-0">
            <ResponsiveContainer width="100%" height="100%">
              <ScatterChart margin={{ top: 12, right: 20, left: 8, bottom: 8 }}>
                <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                <XAxis
                  type="number"
                  dataKey="spreadAtPeak"
                  name="Spread"
                  unit="/mi"
                  tick={{ fontSize: 11 }}
                  domain={[0.5, 0.85]}
                  label={{
                    value: "Equipment spread at peak ($/mi)",
                    position: "insideBottom",
                    offset: -2,
                    style: { fontSize: 11, fill: "#64748b" },
                  }}
                />
                <YAxis
                  type="number"
                  dataKey="bidLift2022"
                  name="Bid lift"
                  unit="%"
                  tick={{ fontSize: 11 }}
                  domain={[5, 22]}
                  label={{
                    value: "Fall-2022 bid lift %",
                    angle: -90,
                    position: "insideLeft",
                    style: { fontSize: 11, fill: "#64748b" },
                  }}
                />
                <ZAxis type="number" dataKey="laneSharePct" range={[80, 400]} />
                <Tooltip
                  cursor={{ strokeDasharray: "3 3" }}
                  formatter={(value: number, name: string) => {
                    if (name === "Bid lift") return [`+${value}%`, name];
                    if (name === "Spread") return [`$${value}/mi`, name];
                    return [value, name];
                  }}
                  labelFormatter={(_, payload) =>
                    payload?.[0]?.payload?.label ?? ""
                  }
                />
                <Scatter data={RENEWAL_SCATTER} name="Sectors">
                  {RENEWAL_SCATTER.map((p) => (
                    <Cell
                      key={p.sector}
                      fill={
                        p.sector === "food-bev"
                          ? COLORS.food
                          : EQUIP_COLORS[p.equipment]
                      }
                    />
                  ))}
                </Scatter>
              </ScatterChart>
            </ResponsiveContainer>
          </div>
          <p className="mt-2 text-xs text-slate-500">
