      {panel === "ladder" && (
        <ChartCard
          title="Sector bid ladder"
          subtitle={`Fall ${bidYear} YoY contract-award lift by shipper vertical ??? food & beverage led 2022 at +${HEADLINE.topSectorBidLiftPct}%`}
